#include <bits/stdc++.h>
using namespace std;
struct C{int type,s,l,m,exit,m2,lm;};
struct R{double w,dd;int orders;};
R run(const vector<int>& p,C c,bool clip=true){int cash=10000,sh=0,pend=0,q=0,trend=0,mr=0,want=0;long long ss=0,sl=0,sm=0;int peak=10000;double dd=0;int orders=0;for(int i=0;i<(int)p.size();i++){int x=p[i], n=0;if(pend==1){n=min(q,max(0,(cash-5)/x));if(n){cash-=n*x+5;sh+=n;orders++;}}else if(pend==2){n=min(q,sh);if(n&&cash+n*x>=5){cash+=n*x-5;sh-=n;orders++;}}int w=cash+sh*x;peak=max(peak,w);dd=max(dd,(double)(peak-w)/peak);ss+=x-(i>=c.s?p[i-c.s]:0);sl+=x-(i>=c.l?p[i-c.l]:0);sm+=x-(i>=c.lm?p[i-c.lm]:0);if(i+1>=max(c.l,c.lm)){long long diff=ss*c.l-sl*c.s, D=(long long)c.s*c.l;int d=x*c.lm-sm;switch(c.type){case 0: if(diff>c.m*D) trend=1;else if(diff<-c.m*D)trend=0; if(d<-c.exit*c.lm)mr=1;else if(d>0)mr=0;want=trend||(mr&&diff>=-c.m2*D);break;case 1:if(d<-c.m*c.lm)want=1;else if(d>c.exit*c.lm)want=0;break;case 2:if(diff>c.m*D)want=1;else if(diff<-c.exit*D)want=0;break;case 3:if(diff>=-c.m2*D&&d<-c.m*c.lm)want=1;else if(d>c.exit*c.lm||diff<-c.m2*D)want=0;break;case 4:if(diff>c.m*D||d<-c.exit*c.lm)want=1;else if(diff<-c.m2*D||d>0)want=0;break;case 5: // revert after large multi-tick price decrease, exit above mean, no trend gate
 if(x-p[i-c.s]<=-c.m)want=1;else if(x*c.lm-sm>c.exit*c.lm)want=0;break;
case 6: // short reversal: compare fast avg vs slow avg
 if(diff<-c.m*D)want=1;else if(diff>c.exit*D)want=0;break;
}}
pend=want?1:2;q=clip?63:(want?min(63,max(0,(cash-5)/x)):min(63,sh));}
return{double(cash+sh*p.back()),dd,orders};}
vector<int> read(string f){ifstream in(f);string s;getline(in,s);vector<int>p;while(getline(in,s)){if(s.empty())continue;p.push_back(stoi(s.substr(s.find(',')+1)));}return p;}
int main(){auto a=read("tb/practica.csv"),b=read("tb/practica_meta.csv");vector<vector<int>> train;for(auto p:{a,b})for(int i=0;i<12000;i+=3000)train.emplace_back(p.begin()+i,p.begin()+i+3000);vector<C>cfg;C base{0,20,120,8,4,4,60};cfg.push_back(base);for(int lm:{4,8,12,16,24,32,48,60,80,120})for(int m:{1,2,3,4,5,6,8})for(int e:{-1,0,1,2,3})cfg.push_back({1,1,1,m,e,0,lm});for(int s:{2,4,8,12,16,20,32})for(int l:{16,32,48,64,80,120})if(s<l)for(int m:{1,2,3,4,6,8})for(int e:{0,1,2,4}){cfg.push_back({2,s,l,m,e,0,1});cfg.push_back({6,s,l,m,e,0,1});}for(int s:{4,8,16,20,32})for(int l:{32,64,120})if(s<l)for(int lm:{12,24,48,60})for(int m:{2,4,6,8})for(int m2:{2,4,8}){cfg.push_back({0,s,l,m,4,m2,lm});cfg.push_back({3,s,l,m,0,m2,lm});cfg.push_back({4,s,l,m,4,m2,lm});}for(int s:{1,2,3,4,8,16})for(int lm:{4,8,16,32,64})for(int m:{1,2,3,4,6})for(int e:{0,1,2})cfg.push_back({5,s,s,m,e,0,lm});vector<pair<double,int>> rank;for(int k=0;k<cfg.size();k++){double score=0;for(auto&p:train){auto r=run(p,cfg[k]);score+=log(max(1.,r.w)/10000.)-.35*r.dd;}rank.push_back({score/8,k});}sort(rank.rbegin(),rank.rend());cout<<"candidates "<<cfg.size()<<"\n";auto show=[&](int k,double sc){auto c=cfg[k];cout<<k<<" "<<sc<<" type "<<c.type<<" "<<c.s<<" "<<c.l<<" "<<c.m<<" "<<c.exit<<" "<<c.m2<<" "<<c.lm;for(auto p:{a,b}){auto r=run(p,c);vector<int> h(p.begin()+12000,p.end());auto t=run(h,c);cout<<" full "<<r.w<<" "<<r.dd<<" test "<<t.w<<" "<<t.dd;}cout<<"\n";};show(0,0);for(int i=0;i<25;i++)show(rank[i].second,rank[i].first); // top per family for prospective selection
for(int t=0;t<=6;t++)for(auto [sc,k]:rank)if(cfg[k].type==t){show(k,sc);break;}
}
